parameters.jsCode:
const candidate = $json.output ?? $json;
const request = $('Normalize & Validate Request').item.json.request;
const allowedUnits = ['g', 'ml', 'piece'];
const ingredientMap = new Map(request.ingredients.map((item) => [item.id, item]));

function resultError(code, message) {
  return [{ json: { valid: false, errorCode: code, errorMessage: message } }];
}
function text(value, field) {
  if (typeof value !== 'string' || !value.trim()) throw new Error(`${field} is missing.`);
  return value.trim();
}
function finite(value, field, positive = false) {
  if (typeof value !== 'number' || !Number.isFinite(value) || (positive ? value <= 0 : value < 0)) {
    throw new Error(`${field} is invalid.`);
  }
  return value;
}
function timeValid(minutes) {
  if (request.preferences.difficulty === 'quick') return minutes > 0 && minutes <= 20;
  if (request.preferences.difficulty === 'medium') return minutes >= 20 && minutes <= 45;
  return minutes >= 45;
}
function nutrition(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw) || !raw.perServing) {
    throw new Error('Nutrition is missing.');
  }
  const per = raw.perServing;
  const energyKcal = finite(per.energyKcal, 'energyKcal');
  const macro = (value, label) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`${label} is missing.`);
    const grams = finite(value.grams, `${label}.grams`);
    const percent = finite(value.percent, `${label}.percent`);
    if (percent > 100) throw new Error(`${label}.percent is greater than 100.`);
    return { grams, percent };
  };
  const perServing = {
    energyKcal,
    protein: macro(per.protein, 'protein'),
    carbs: macro(per.carbs, 'carbs'),
    fat: macro(per.fat, 'fat'),
  };
  const total = {
    energyKcal: perServing.energyKcal * request.servings,
    protein: { grams: perServing.protein.grams * request.servings, percent: perServing.protein.percent },
    carbs: { grams: perServing.carbs.grams * request.servings, percent: perServing.carbs.percent },
    fat: { grams: perServing.fat.grams * request.servings, percent: perServing.fat.percent },
  };
  return { perServing, total };
}
function directions(raw, cookingTimeMinutes) {
  if (!Array.isArray(raw) || !raw.length) throw new Error('Directions are missing.');
  const groups = new Map();
  const assigned = new Set();
  const built = raw.map((direction, index) => {
    if (!direction || typeof direction !== 'object' || Array.isArray(direction)) throw new Error('Direction is invalid.');
    if (direction.step !== index + 1) throw new Error('Direction steps must be consecutive.');
    const cooks = direction.assignedCooks;
    if (!Array.isArray(cooks) || !cooks.length) throw new Error('assignedCooks is missing.');
    const unique = new Set();
    cooks.forEach((cook) => {
      if (!Number.isInteger(cook) || cook < 1 || cook > request.cookCount || unique.has(cook)) {
        throw new Error('assignedCooks is invalid.');
      }
      unique.add(cook);
      assigned.add(cook);
    });
    const result = {
      step: index + 1,
      title: text(direction.title, 'Direction title'),
      instruction: text(direction.instruction, 'Direction instruction'),
      assignedCooks: [...unique],
    };
    if (direction.waitingTimeMinutes !== undefined) {
      const waiting = finite(direction.waitingTimeMinutes, 'waitingTimeMinutes');
      if (waiting > cookingTimeMinutes) throw new Error('Waiting time exceeds the total cooking time.');
      result.waitingTimeMinutes = waiting;
    }
    if (direction.parallelGroup !== undefined) {
      const groupName = text(direction.parallelGroup, 'parallelGroup');
      result.parallelGroup = groupName;
      const existing = groups.get(groupName);
      if (existing) {
        if (existing.lastIndex !== index - 1) throw new Error('Parallel group is not contiguous.');
        if ([...unique].some((cook) => existing.cooks.has(cook))) throw new Error('A parallel group assigns the same cook more than once.');
        unique.forEach((cook) => existing.cooks.add(cook));
        existing.count += 1;
        existing.lastIndex = index;
      } else {
        groups.set(groupName, { lastIndex: index, cooks: new Set(unique), count: 1 });
      }
    }
    return result;
  });
  for (let cook = 1; cook <= request.cookCount; cook++) {
    if (!assigned.has(cook)) {
  throw new Error(`Cook ${cook} does not have a task.`);
}
  }
  if ([...groups.values()].some((group) => group.count < 2)) throw new Error('Parallel group must contain at least two steps.');
  if (request.cookCount > 1 && groups.size === 0) throw new Error('For multiple cooks a parallelgroup is missing');
  return built;
}

try {
  if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate) || !Array.isArray(candidate.recipes)) {
    throw new Error('recipes is missing.');
  }
  if (candidate.recipes.length !== 3) throw new Error('The AI must return exactly three recipes.');

  const titles = new Set();
  const methods = new Set();
  const recipes = candidate.recipes.map((recipe, index) => {
    if (!recipe || typeof recipe !== 'object' || Array.isArray(recipe)) throw new Error('Recipe is invalid');
    const title = text(recipe.title, 'title');
    const titleKey = title.toLocaleLowerCase('en');
    if (titles.has(titleKey)) throw new Error('Recipe titles are not unique.');
    titles.add(titleKey);

    const cookingTimeMinutes = finite(recipe.cookingTimeMinutes, 'cookingTimeMinutes', true);
    if (!Number.isInteger(cookingTimeMinutes) || !timeValid(cookingTimeMinutes)) {
      throw new Error('Cooking time does not match the selected difficulty.');
    }

    if (!Array.isArray(recipe.ingredients) || !recipe.ingredients.length) throw new Error('ingredients are missing.');
    const seen = new Set();
    const ingredients = recipe.ingredients.map((item) => {
      if (!item || typeof item !== 'object' || Array.isArray(item)) throw new Error('Recipe ingredient is invalid.');
      const sourceIngredientId = text(item.sourceIngredientId, 'sourceIngredientId');
      const source = ingredientMap.get(sourceIngredientId);
      if (!source || seen.has(sourceIngredientId)) throw new Error('Unknown or duplicate sourceIngredientId.');
      seen.add(sourceIngredientId);
      const amount = finite(item.amount, 'ingredient amount', true);
      if (amount > source.amount) throw new Error('Recipe uses more of an ingredient than is available.');
      return { sourceIngredientId, name: source.name, amount, unit: source.unit };
    });
    if (seen.size / request.ingredients.length < 0.7) throw new Error('Ingredient coverage is below 70 percent.');

    const extrasRaw = recipe.additionalIngredients ?? [];
    if (!Array.isArray(extrasRaw) || extrasRaw.length > 3) throw new Error('Too many additional pantry ingredients.');
    const userNames = new Set(request.ingredients.map((item) => item.name.trim().toLocaleLowerCase('en')));
    const additionalIngredients = extrasRaw.map((item) => {
      if (!item || typeof item !== 'object' || Array.isArray(item) || 'sourceIngredientId' in item) {
        throw new Error('Additional ingredient is invalid.');
      }
      const name = text(item.name, 'additional ingredient name');
      if (userNames.has(name.toLocaleLowerCase('en'))) throw new Error('An existing ingredient was duplicated as an additional ingredient.');
      const amount = finite(item.amount, 'additional ingredient amount', true);
      if (!allowedUnits.includes(item.unit)) throw new Error('Additional ingredient has an invalid unit.');
      return { name, amount, unit: item.unit };
    });

    const builtDirections = directions(recipe.directions, cookingTimeMinutes);
    const methodKey = builtDirections.map((item) => item.instruction.trim().toLocaleLowerCase('en')).join('|');
    if (methods.has(methodKey)) throw new Error('Recipes are not sufficiently different.');
    methods.add(methodKey);

    return {
      id: `${request.clientRequestId}-${index + 1}`,
      title,
      cuisine: request.preferences.cuisine,
      difficulty: request.preferences.difficulty,
      diet: request.preferences.diet,
      cookingTimeMinutes,
      servings: request.servings,
      cookCount: request.cookCount,
      nutrition: nutrition(recipe.nutrition),
      ingredients,
      additionalIngredients,
      directions: builtDirections,
      rank: index + 1,
    };
  });

  const response = {
    schemaVersion: 2,
    clientRequestId: request.clientRequestId,
    recipes,
  };
  const createdAt = new Date().toISOString();
  const firebaseRecords = Object.fromEntries(
    recipes.map((recipe) => [
      recipe.id,
      { schemaVersion: 2, createdAt, payload: recipe },
    ]),
  );

  return [{ json: { valid: true, response, firebaseRecords } }];
} catch (error) {
  return resultError(
    'invalid_ai_response',
    error instanceof Error ? error.message : 'The AI response failed domain validation.',
  );
}

const day =
  $json && typeof $json === 'object'
    ? $json
    : {};

const source =
  $('Normalize & Validate Request').item.json;

const ipUsedRecipes = Number(
  day.byIp?.[source.clientIpKey]?.usedRecipes ?? 0
);

const globalUsedRecipes = Number(
  day.globalUsedRecipes ?? 0
);

const ipLimitRecipes = 3;
const globalLimitRecipes = 12;

const ipRemainingRecipes =
  Math.max(
    0,
    ipLimitRecipes - ipUsedRecipes
  );

const globalRemainingRecipes =
  Math.max(
    0,
    globalLimitRecipes - globalUsedRecipes
  );

const allowed =
  ipRemainingRecipes >= 3 &&
  globalRemainingRecipes >= 3;

const reason =
  ipRemainingRecipes < 3
    ? 'ip_limit_reached'
    : (
        globalRemainingRecipes < 3
          ? 'global_limit_reached'
          : null
      );

return [{
  json: {
    allowed,
    reason,

    dayKey:
      $now
        .setZone('Europe/Berlin')
        .toISODate(),

    clientIpKey:
      source.clientIpKey,

    ipUsedRecipes,
    ipLimitRecipes,
    ipRemainingRecipes,

    globalUsedRecipes,
    globalLimitRecipes,
    globalRemainingRecipes,
  },
}];

