parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "recipes": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "title": {
            "type": "string",
            "minLength": 1
          },
          "cookingTimeMinutes": {
            "type": "number",
            "minimum": 1
          },
          "ingredients": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "sourceIngredientId": {
                  "type": "string",
                  "minLength": 1
                },
                "amount": {
                  "type": "number",
                  "exclusiveMinimum": 0
                }
              },
              "required": [
                "sourceIngredientId",
                "amount"
              ]
            }
          },
          "additionalIngredients": {
            "type": "array",
            "maxItems": 3,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "name": {
                  "type": "string",
                  "minLength": 1
                },
                "amount": {
                  "type": "number",
                  "exclusiveMinimum": 0
                },
                "unit": {
                  "type": "string",
                  "enum": ["g", "ml", "piece"]
                }
              },
              "required": [
                "name",
                "amount",
                "unit"
              ]
            }
          },
          "nutrition": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "perServing": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "energyKcal": {
                    "type": "number",
                    "minimum": 0
                  },
                  "protein": {
                    "$ref": "#/$defs/macro"
                  },
                  "carbs": {
                    "$ref": "#/$defs/macro"
                  },
                  "fat": {
                    "$ref": "#/$defs/macro"
                  }
                },
                "required": [
                  "energyKcal",
                  "protein",
                  "carbs",
                  "fat"
                ]
              }
            },
            "required": ["perServing"]
          },
          "directions": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "step": {
                  "type": "integer",
                  "minimum": 1
                },
                "title": {
                  "type": "string",
                  "minLength": 1
                },
                "instruction": {
                  "type": "string",
                  "minLength": 1
                },
                "assignedCooks": {
                  "type": "array",
                  "minItems": 1,
                  "items": {
                    "type": "integer",
                    "minimum": 1,
                    "maximum": 3
                  }
                },
                "parallelGroup": {
                  "type": "string",
                  "minLength": 1
                },
                "waitingTimeMinutes": {
                  "type": "number",
                  "minimum": 0
                }
              },
              "required": [
                "step",
                "title",
                "instruction",
                "assignedCooks"
              ]
            }
          }
        },
        "required": [
          "title",
          "cookingTimeMinutes",
          "ingredients",
          "additionalIngredients",
          "nutrition",
          "directions"
        ]
      }
    }
  },
  "required": ["recipes"],
  "$defs": {
    "macro": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "grams": {
          "type": "number",
          "minimum": 0
        },
        "percent": {
          "type": "number",
          "minimum": 0,
          "maximum": 100
        }
      },
      "required": [
        "grams",
        "percent"
      ]
    }
  }
}
